+  border-top: 1px solid var(--hair-1);
+}
+.evidence-disclosure--panel {
+  border: 1px solid var(--hair-1);
+  border-radius: var(--r-md);
+  background: color-mix(in oklab, var(--void-1) 88%, transparent);
+}
+.evidence-disclosure > summary {
+  display: flex;
+  min-height: 44px;
+  box-sizing: border-box;
+  align-items: center;
+  justify-content: space-between;
+  gap: 16px;
+  padding: 13px 0;
+  color: var(--muted);
+  cursor: pointer;
+  list-style: none;
+}
+.evidence-disclosure--panel > summary {
+  padding: 15px 18px;
+}
+.evidence-disclosure > summary::-webkit-details-marker {
+  display: none;
+}
+.evidence-disclosure > summary::after {
+  content: "+";
+  flex: 0 0 auto;
+  width: 22px;
+  height: 22px;
+  border: 1px solid var(--hair-2);
+  border-radius: 50%;
+  color: var(--faint);
+  font-family: var(--font-mono);
+  font-size: 14px;
+  font-weight: 400;
+  line-height: 20px;
+  text-align: center;
+}
+.evidence-disclosure[open] > summary::after {
+  content: "\2212";
+}
+.evidence-disclosure > summary:focus-visible {
+  outline: 2px solid var(--ink-0);
+  outline-offset: 4px;
+  border-radius: 2px;
+}
+.evidence-disclosure__summary {
+  display: grid;
+  gap: 2px;
+  min-width: 0;
+}
+.evidence-disclosure__summary strong {
+  color: currentColor;
+  font-size: 12px;
+  font-weight: 650;
+  line-height: 1.35;
+}
+.evidence-disclosure__summary small {
+  color: var(--faint);
+  font-size: 10.5px;
+  font-weight: 400;
+  line-height: 1.45;
+}
+.evidence-disclosure__body {
+  display: grid;
+  gap: 12px;
+  padding: 0 0 15px;
+  color: var(--faint);
+  font-size: 11.5px;
+  line-height: 1.65;
+}
+.evidence-disclosure--panel .evidence-disclosure__body {
+  padding: 0 18px 17px;
+}
+.evidence-disclosure__body > :first-child {
+  margin-top: 0;
+}
+.evidence-disclosure__body > :last-child {
+  margin-bottom: 0;
+}
+.evidence-disclosure__list {
+  display: grid;
+  gap: 9px;
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+.evidence-disclosure__receipt {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  min-width: 0;
+  color: var(--faint);
+  font-size: 10.5px;
+  line-height: 1.55;
+  letter-spacing: 0.04em;
+}
+.evidence-disclosure__links {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px 12px;
+  margin: 0;
+}
+.evidence-disclosure__links a {
+  color: var(--muted);
+  text-underline-offset: 3px;
+}
+@media (hover: hover) and (pointer: fine) {
+  .evidence-disclosure > summary:hover {
+    color: var(--text-2);
+  }
+}

